import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import ConfirmModal from 'views/admin/Common/ConfirmModal';
import colors from 'config/colors';

const sectionLabel = {
  fontSize: 11,
  fontWeight: 'bold',
  letterSpacing: 0.6,
  textTransform: 'uppercase',
  color: colors.grey3,
  marginBottom: 3,
};

// Asks before a stop-name rename, in two steps: this dialog lists every stop of the route that is saved under another
// route name (the name it has now and the one it will get), and pressing the button then raises a last Yes / No alert, so
// nothing is changed by one click. `stops` are the stops to rename. It opens from "Fix now", and with `assign` also from
// Add Bus & Driver, where the same rename would otherwise happen silently before the assignment is saved.
const FixStopNamesModal = ({ isOpen, route, stops, saving, assign, onConfirm, onClose }) => {
  const [sure, setSure] = useState(false); // the last "are you sure?" alert

  // A dialog that is closed (cancelled or finished) always starts again at the list, never at the alert.
  useEffect(() => {
    if (!isOpen) setSure(false);
  }, [isOpen]);

  return (
    <Modal isOpen={isOpen} toggle={saving ? undefined : onClose} size="lg">
      <ModalHeader toggle={saving ? undefined : onClose}>
        {assign ? 'Rename stops before assigning' : 'Fix stop route names'}
      </ModalHeader>
      <ModalBody>
        {!!route && (
          <>
            <div style={{ marginBottom: 14 }}>
              <div style={sectionLabel}>Route</div>
              <div style={{ fontSize: 16, fontWeight: 'bold', color: colors.grey1 }}>{route.description}</div>
            </div>
            <div style={{ marginBottom: 14 }}>
              <div style={sectionLabel}>What is wrong</div>
              <div>
                Every stop has a route name saved on it. The driver&apos;s app finds a route&apos;s students through
                that name, so it has to match the route exactly.{' '}
                <b>{stops.length === 1 ? '1 stop below has' : `${stops.length} stops below have`} a different name</b>,
                so {stops.length === 1 ? 'its' : 'their'} students don&apos;t show for the driver.
              </div>
            </div>
            <div style={{ marginBottom: 14 }}>
              <div style={sectionLabel}>{assign ? 'What happens next' : 'What Fix does'}</div>
              <div>
                {assign && (
                  <>
                    The bus and driver are <b>not assigned yet</b>. To assign them, the stops below are renamed first.{' '}
                  </>
                )}
                It changes only that saved route name to <b>{route.description}</b>. The stop names, distances, fees and
                students are not touched.
              </div>
            </div>
            <div style={sectionLabel}>{stops.length === 1 ? 'Stop to fix' : 'Stops to fix'}</div>
            <div style={{ overflowX: 'auto', border: '1px solid #eee', borderRadius: 6 }}>
              <table className="table mb-0" style={{ fontSize: 14 }}>
                <thead>
                  <tr style={{ color: colors.grey3 }}>
                    <th>Stop</th>
                    <th>Route name saved now</th>
                    <th>Will change to</th>
                  </tr>
                </thead>
                <tbody>
                  {stops.map(stop => (
                    <tr key={stop.transportAreaId}>
                      <td>
                        <b>{stop.areaName}</b>
                      </td>
                      <td style={{ color: '#c62828' }}>{stop.ruteName || '--'}</td>
                      <td style={{ color: '#2e7d32', fontWeight: 'bold' }}>{route.description}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}
      </ModalBody>
      <ModalFooter>
        {/* mr-2 puts the gap between the two buttons, as in the other dialogs of this page */}
        <CustomButton className="mr-2" color="default" name="Cancel" onClick={onClose} disabled={saving} />
        <CustomButton
          name={assign ? 'Rename & assign' : stops.length === 1 ? 'Fix 1 stop' : `Fix ${stops.length} stops`}
          showLoader={true}
          loading={saving}
          disabled={saving || !stops.length}
          onClick={() => setSure(true)}
        />
      </ModalFooter>
      <ConfirmModal
        confirmModalOpen={sure}
        loading={saving}
        confirmMessage={
          assign
            ? `Rename ${stops.length === 1 ? '1 stop' : `${stops.length} stops`} to "${
                route?.description
              }" and assign the bus and driver to this route?`
            : `Rename ${stops.length === 1 ? '1 stop' : `${stops.length} stops`} to "${
                route?.description
              }"? This changes the saved route name on ${stops.length === 1 ? 'it' : 'them'}.`
        }
        deleteConfirm={onConfirm}
        deleteCancel={() => setSure(false)}
      />
    </Modal>
  );
};

export default FixStopNamesModal;
