import React from 'react';
import { Redirect } from 'react-router-dom';
import TransportPage from './TransportPage';
import BusAttendancePage from './BusAttendancePage';

// Transport has a sidebar page each for Buses, Drivers, Routes & stops, Bus assignment and Bus attendance.
export const BusesRoutePage = () => <TransportPage section="buses" />;
export const DriversRoutePage = () => <TransportPage section="drivers" />;
export const RoutesRoutePage = () => <TransportPage section="routes" />;
export const AssignmentRoutePage = () => <TransportPage section="assignment" />;
export const BusAttendanceRoutePage = BusAttendancePage;

// The old single Transport page (?tab=drivers, ?tab=assign ...): old links land on the page that tab became.
export const LegacyTransportRedirect = ({ location }) => {
  const tab = new URLSearchParams(location?.search).get('tab');
  if (tab === 'drivers') return <Redirect to="/admin/transport/drivers" />;
  if (tab === 'routes') return <Redirect to="/admin/transport/routes" />;
  if (tab === 'assign') return <Redirect to="/admin/transport/assignment?tab=driver" />;
  if (tab === 'students') return <Redirect to="/admin/transport/assignment?tab=students" />;
  return <Redirect to="/admin/transport/buses" />;
};
