import React from 'react';
import { useState } from 'react';
import { Row, Col } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import MuiTable from 'views/admin/Common/MuiTable';
import { CommonLoader } from 'views/admin/Common/Loader';
import { formResMessage, formUsernameFromEmail, usernameTextColor } from 'utils/commonFunc';
import {
  saveDriverApi,
  updateDriverApi,
  deleteDriverApi,
  DRIVER_DESIGNATION,
  DRIVER_DEPARTMENT,
} from 'actions/admin/transport';
import colors from 'config/colors';
import DriverFormModal from './DriverFormModal';

// Drivers: school employees (non-teaching, "Driver" designation), managed through the same
// employee endpoints School Staffs uses. Which bus/route a driver is on comes from the page's
// loaded assignments (read-only here - assigning happens from the Routes tab).
const DriversTab = ({
  schoolId,
  loggedUserToken,
  showWarning,
  drivers,
  isLoading,
  reload,
  onViewAssignment,
  refreshAssignments,
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editDriver, setEditDriver] = useState(null);
  const [saving, setSaving] = useState(false);

  const openAdd = () => {
    setEditDriver(null);
    setIsModalOpen(true);
  };

  const openEdit = employeeId => {
    setEditDriver(drivers.find(d => d.employeeId === employeeId));
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditDriver(null);
  };

  // Rejects on failure so the form can show the server's message inline; resolves after closing.
  const handleSave = async formData => {
    setSaving(true);
    try {
      if (editDriver) {
        // The update replaces every field, so send the whole existing record with the form's changes on top.
        await updateDriverApi({
          employeeId: editDriver.employeeId,
          postData: { ...editDriver, ...formData },
          token: loggedUserToken,
        });
      } else {
        await saveDriverApi({
          postData: {
            ...formData,
            employerOrgId: schoolId,
            designation: DRIVER_DESIGNATION,
            department: DRIVER_DEPARTMENT,
            status: 'ACTIVE',
          },
          token: loggedUserToken,
        });
      }
      showWarning(editDriver ? 'Driver updated successfully' : 'Driver added successfully', 'success');
      setSaving(false);
      closeModal();
      reload();
    } catch (err) {
      setSaving(false);
      throw err;
    }
  };

  // MuiTable confirms before calling this, so it only ever runs after the admin said yes once.
  const handleDelete = async employeeId => {
    // An assigned driver is unassigned first, so they are not deleted while still on a route. Checked live.
    const current = await refreshAssignments();
    if (current.some(a => a.employeeId === employeeId)) {
      showWarning('This driver is assigned to a bus and route. Unassign them first, then delete the driver.', 'error');
      return;
    }
    try {
      await deleteDriverApi({ employeeId, token: loggedUserToken });
      showWarning('Driver deleted successfully', 'success');
      reload();
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
  };

  const rows = drivers.map(driver => {
    return {
      ...driver,
      nameLabel: (
        <span>
          <div>{`${driver.name} (${driver.code})`}</div>
          <div style={{ color: usernameTextColor }}>{formUsernameFromEmail(driver.email)}</div>
        </span>
      ),
      experienceLabel: driver.totalExperience || '--',
    };
  });

  if (isLoading) return <CommonLoader />;

  return (
    <>
      <Row className="mb-2" style={{ alignItems: 'center' }}>
        <Col style={{ textAlign: 'right' }}>
          <CustomButton
            size="small"
            name="+ Add Driver"
            onClick={openAdd}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </Col>
      </Row>
      <MuiTable
        tableHeaders={['Name & Code', 'Phone', 'Experience', 'Action']}
        tableBodyData={{ content: rows }}
        bodyColumns={['nameLabel', 'phoneNumber', 'experienceLabel', 'action']}
        idName="employeeId"
        dropDownActions={['edit', 'delete']}
        fetchItem={openEdit}
        deleteItem={handleDelete}
        hidePagination={true}
        renderRowExtra={driver => (
          <CustomButton
            size="small"
            variant="outlined"
            name="View assignment"
            onClick={() => onViewAssignment({ driverId: driver.employeeId })}
          />
        )}
      />
      <DriverFormModal
        isOpen={isModalOpen}
        editDriver={editDriver}
        saving={saving}
        onClose={closeModal}
        onSave={handleSave}
      />
    </>
  );
};

export default DriversTab;
