import React from 'react';
import { FormGroup, Label } from 'reactstrap';
import DatePicker from 'react-datepicker';
import moment from 'moment';

// Date picker bound to a 'YYYY-MM-DD' string (the format the backend takes for date-only fields),
// same look as the date fields in the employee/student forms.
const DateField = ({ label, name, value, onChange, error, required, minDate, maxDate }) => (
  <FormGroup className="customDatePickerWidth">
    <Label htmlFor="">
      {label}
      {required && <sup> *</sup>}
    </Label>
    <br />
    <DatePicker
      className="form-control"
      selected={value ? moment(value).toDate() : null}
      onChange={date => onChange(name, date ? moment(date).format('YYYY-MM-DD') : '')}
      dateFormat="dd/MM/yyyy"
      showMonthDropdown
      showYearDropdown
      dropdownMode="select"
      placeholderText="Select date..."
      minDate={minDate}
      maxDate={maxDate}
    />
    {error && <span className="err-msg">{error}</span>}
  </FormGroup>
);

export default DateField;
