import React from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useHistory, useLocation } from 'react-router-dom';
import { Paper, Tabs, Tab } from '@material-ui/core';
import { getGlobalSchoolUtils, getGlobalCurrentBatchUtils } from 'utils/commonFunc';
import { showToast } from 'actions/admin/auth';
import { fetchSchoolAssignments } from 'actions/admin/transport';
import colors from 'config/colors';
import BusesTab from './components/BusesTab';
import DriversTab from './components/DriversTab';
import RoutesTab from './components/RoutesTab';
import { useTransportData, indexBy } from './useTransportData';

// Transport has a sidebar page each for Buses, Drivers, Routes & stops and Bus assignment (in that order, which is the
// order the setup is done in). Bus assignment has two tabs: which driver is on which bus for each route, and which
// students ride each route.
const ASSIGNMENT_TABS = [
  { key: 'driver', label: 'Driver to bus' },
  { key: 'students', label: 'Students to bus' },
];

// Transport: buses, drivers, routes and the bus assignment, one sidebar page each (`section`). They share what they show
// about each other (a bus's route and driver, a driver's route and bus, a route's students), so everything is loaded here
// once and handed down; a page calls reload() after any change. Admin gating happens one level up, in AdminRoutes.jsx's
// accessRoles for these routes.
const TransportPage = ({ section = 'buses' }) => {
  const dispatch = useDispatch();
  const history = useHistory();
  const location = useLocation();
  const loggedUserToken = useSelector(state => state.auth.loggedUserToken);
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  const { batchId } = getGlobalCurrentBatchUtils();
  const showWarning = (message, type) => dispatch(showToast(message, type));
  // Loaded once for the page; only the first load shows a spinner, later reloads refresh in place (see the hook).
  const {
    data,
    isLoading,
    reload: loadAll,
  } = useTransportData({
    schoolId,
    batchId,
    token: loggedUserToken,
    onError: message => showWarning(message, 'error'),
  });
  // Bus assignment's tab and filter live in the URL (?tab=students, ?bus=3, ?driver=5), so a refresh or a link from a bus or
  // a driver lands on the same view.
  const query = new URLSearchParams(location.search);
  const assignmentTab = query.get('tab') === 'students' ? 1 : 0;
  const assignmentFilter = { busId: Number(query.get('bus')) || null, driverId: Number(query.get('driver')) || null };

  const changeAssignmentTab = (event, index) => {
    history.push(`${location.pathname}?tab=${ASSIGNMENT_TABS[index].key}`);
  };
  // A bus's or driver's "View assignment": the Bus assignment page, showing only that bus's or driver's routes.
  const viewAssignment = ({ busId, driverId }) =>
    history.push(`/admin/transport/assignment?tab=driver&${busId ? `bus=${busId}` : `driver=${driverId}`}`);

  if (!schoolId) {
    return (
      <div className="content">
        <div style={{ textAlign: 'center', color: '#9a9a9a', padding: 40 }}>Please select a school.</div>
      </div>
    );
  }

  const shared = {
    schoolId,
    loggedUserToken,
    showWarning,
    isLoading,
    reload: loadAll,
    refreshAssignments: () => fetchSchoolAssignments({ schoolId, batchId, token: loggedUserToken }),
    onViewAssignment: viewAssignment,
    buses: data.buses,
    drivers: data.drivers,
    assignments: data.assignments,
    routesById: indexBy(data.routes, 'transportFeeStructId'),
    busesById: indexBy(data.buses, 'busId'),
    driversById: indexBy(data.drivers, 'employeeId'),
  };
  const routeProps = {
    ...shared,
    batchId,
    routes: data.routes,
    areasByRoute: data.areasByRoute,
    studentsByRoute: data.studentsByRoute,
    takenStudentIds: data.takenStudentIds,
  };
  const content = {
    buses: <BusesTab {...shared} />,
    drivers: <DriversTab {...shared} />,
    routes: <RoutesTab view="routes" {...routeProps} />,
    assignment:
      assignmentTab === 0 ? (
        <RoutesTab
          key="assign"
          view="assign"
          {...routeProps}
          assignmentFilter={assignmentFilter}
          onClearFilter={() => history.push('/admin/transport/assignment?tab=driver')}
        />
      ) : (
        <RoutesTab key="students" view="students" {...routeProps} />
      ),
  }[section];

  return (
    <div className="content">
      {section === 'assignment' && (
        <Paper square style={{ marginBottom: 16 }}>
          <Tabs
            value={assignmentTab}
            onChange={changeAssignmentTab}
            TabIndicatorProps={{ style: { display: 'none' } }}
            textColor="inherit"
            variant="scrollable"
            scrollButtons="on">
            {ASSIGNMENT_TABS.map((tab, index) => (
              <Tab
                key={tab.key}
                label={tab.label}
                style={{
                  fontWeight: 'bold',
                  color: assignmentTab === index ? colors.accent : '',
                  borderBottom: assignmentTab === index ? `3px solid ${colors.accent}` : '',
                }}
              />
            ))}
          </Tabs>
        </Paper>
      )}
      {content}
    </div>
  );
};

export default TransportPage;
