import React from 'react';
import { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col } from 'reactstrap';
import CustomInput from 'views/admin/Common/CustomInput';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import DateField from './DateField';
import { BUS_DOC_FIELDS, BUS_STATUS_OPTIONS, FUEL_OPTIONS } from '../transportUtils';

const emptyForm = {
  busNumber: '',
  registrationNumber: '',
  make: '',
  model: '',
  manufactureYear: '',
  seatingCapacity: '',
  fuelType: null,
  status: 'ACTIVE',
  gpsDeviceId: '',
  chassisNumber: '',
  engineNumber: '',
  insuranceExpiryDate: '',
  fitnessExpiryDate: '',
  permitExpiryDate: '',
  pollutionExpiryDate: '',
  remarks: '',
};

// A small heading that splits the long form into what it is about.
const sectionStyle = {
  fontSize: 12,
  fontWeight: 'bold',
  letterSpacing: '0.06em',
  textTransform: 'uppercase',
  color: colors.accent,
  borderBottom: `1px solid ${colors.accent}22`,
  paddingBottom: 4,
  margin: '14px 0 12px',
};

const validate = data => {
  const errors = {};
  if (!data.busNumber?.trim()) errors.busNumber = 'Bus number is required';
  if (data.seatingCapacity !== '' && !(Number(data.seatingCapacity) > 0)) {
    errors.seatingCapacity = 'Seating capacity must be a positive number';
  }
  const year = Number(data.manufactureYear);
  if (data.manufactureYear !== '' && (year < 1980 || year > new Date().getFullYear() + 1)) {
    errors.manufactureYear = 'Enter a valid year';
  }
  return errors;
};

const BusFormModal = ({ isOpen, editBus, saving, onClose, onSave }) => {
  const [data, setData] = useState(emptyForm);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    if (isOpen) {
      setData(
        editBus
          ? Object.keys(emptyForm).reduce((acc, key) => ({ ...acc, [key]: editBus[key] ?? emptyForm[key] }), {})
          : emptyForm
      );
      setErrors({});
    }
  }, [isOpen]);

  const handleChange = (name, value) => setData(prev => ({ ...prev, [name]: value }));

  const handleSubmit = e => {
    e.preventDefault();
    const nextErrors = validate(data);
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length) return;
    // Empty optional fields go to the backend as null, not '' (dates in particular can't be '').
    const payload = Object.keys(data).reduce(
      (acc, key) => ({ ...acc, [key]: data[key] === '' ? null : data[key] }),
      {}
    );
    onSave({
      ...payload,
      busNumber: data.busNumber.trim(),
      seatingCapacity: data.seatingCapacity === '' ? null : Number(data.seatingCapacity),
      manufactureYear: data.manufactureYear === '' ? null : Number(data.manufactureYear),
    });
  };

  return (
    <Modal size="lg" isOpen={isOpen} toggle={onClose}>
      <form onSubmit={handleSubmit}>
        <ModalHeader toggle={onClose}>
          <span style={{ whiteSpace: 'nowrap' }}>{editBus ? 'UPDATE BUS' : 'ADD BUS'}</span>
        </ModalHeader>
        <ModalBody>
          <Row>
            <Col xs={12}>
              <div style={sectionStyle}>Bus details</div>
            </Col>
            <Col sm={6}>
              <CustomInput
                label={
                  <>
                    Bus Number<sup> *</sup>
                  </>
                }
                name="busNumber"
                placeholder="e.g. Bus 1"
                value={data.busNumber}
                onChange={handleChange}
                error={errors.busNumber}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Registration Number"
                name="registrationNumber"
                placeholder="e.g. TN09AB1234"
                value={data.registrationNumber}
                onChange={handleChange}
              />
            </Col>
            <Col sm={6}>
              <CustomInput label="Make" name="make" value={data.make} onChange={handleChange} />
            </Col>
            <Col sm={6}>
              <CustomInput label="Model" name="model" value={data.model} onChange={handleChange} />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Manufacture Year"
                name="manufactureYear"
                type="number"
                value={data.manufactureYear}
                onChange={handleChange}
                error={errors.manufactureYear}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Seating Capacity"
                name="seatingCapacity"
                type="number"
                value={data.seatingCapacity}
                onChange={handleChange}
                error={errors.seatingCapacity}
              />
            </Col>
            <Col sm={6}>
              <CustomSelect
                label="Fuel Type"
                name="fuelType"
                usePortal
                value={data.fuelType}
                options={FUEL_OPTIONS}
                onChange={handleChange}
              />
            </Col>
            <Col sm={6}>
              <CustomSelect
                label="Status"
                name="status"
                usePortal
                value={data.status}
                options={BUS_STATUS_OPTIONS}
                onChange={handleChange}
              />
            </Col>

            <Col xs={12}>
              <div style={sectionStyle}>Documents - expiry dates</div>
            </Col>
            {BUS_DOC_FIELDS.map(({ key, label }) => (
              <Col sm={6} key={key}>
                <DateField label={`${label} Expiry`} name={key} value={data[key]} onChange={handleChange} />
              </Col>
            ))}

            <Col xs={12}>
              <div style={sectionStyle}>Identification</div>
            </Col>
            <Col sm={6}>
              <CustomInput label="GPS Device ID" name="gpsDeviceId" value={data.gpsDeviceId} onChange={handleChange} />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Chassis Number"
                name="chassisNumber"
                value={data.chassisNumber}
                onChange={handleChange}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Engine Number"
                name="engineNumber"
                value={data.engineNumber}
                onChange={handleChange}
              />
            </Col>
            <Col sm={12}>
              <CustomInput
                label="Remarks"
                name="remarks"
                type="textarea"
                placeholder="Optional..."
                value={data.remarks}
                onChange={handleChange}
              />
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={saving}
            onClick={onClose}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            name="Save"
            disabled={saving}
            loading={saving}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default BusFormModal;
