import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import moment from 'moment';
import Paper from '@material-ui/core/Paper';
import Checkbox from '@material-ui/core/Checkbox';
import FormControlLabel from '@material-ui/core/FormControlLabel';
import { Row, Col, Label } from 'reactstrap';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import { showToast } from 'actions/admin/auth';
import { fetchRouteStudentsApi, markBusAttendanceApi } from 'actions/admin/transport';
import { formResMessage, getGlobalCurrentBatchUtils, getGlobalSchoolUtils } from 'utils/commonFunc';
import EmptyState from 'views/admin/Common/EmptyState';
import StatTile from 'views/admin/Common/StatTile';
import { SkeletonRows } from 'views/admin/Common/Loader';
import { useTransportData } from './useTransportData';

const TRIPS = [
  { value: 'PICKUP', label: 'Pickup (to school)', present: 'PICKED', presentLabel: 'Picked up' },
  { value: 'DROP', label: 'Drop (home)', present: 'DROPPED', presentLabel: 'Dropped' },
];
const STATUS_COLORS = { PICKED: '#2e7d32', DROPPED: '#2e7d32', ABSENT: '#c62828' };

// One tick box of a student's row (Picked / Dropped, Absent) - the same two boxes the app shows. Both left empty means not
// marked yet; ticking a ticked box clears it.
const TickBox = ({ label, color, checked, onChange }) => (
  <FormControlLabel
    style={{ margin: 0 }}
    label={
      <span style={{ fontSize: 12, color: checked ? color : '#6b778a', fontWeight: checked ? 'bold' : 'normal' }}>
        {label}
      </span>
    }
    control={
      <Checkbox size="small" checked={checked} onChange={onChange} style={{ color: checked ? color : undefined }} />
    }
  />
);

// Admin marks a bus's pickup or drop for the students of its route (the same attendance the driver marks in the app): pick
// the bus (through the driver on it), the trip and the day, then mark each student. Nothing is marked until it is saved, and
// saving again for the same day and trip simply updates it.
const BusAttendancePage = () => {
  const dispatch = useDispatch();
  const token = useSelector(state => state.auth.loggedUserToken);
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  const { batchId } = getGlobalCurrentBatchUtils();
  const showWarning = useCallback((message, type) => dispatch(showToast(message, type)), [dispatch]);
  const { data, isLoading } = useTransportData({
    schoolId,
    batchId,
    token,
    onError: message => showWarning(message, 'error'),
  });

  const [assignmentId, setAssignmentId] = useState('');
  const [tripType, setTripType] = useState('PICKUP');
  const [date, setDate] = useState(moment().format('YYYY-MM-DD'));
  const [students, setStudents] = useState([]);
  const [statuses, setStatuses] = useState({});
  const [loadingStudents, setLoadingStudents] = useState(false);
  const [saving, setSaving] = useState(false);

  const trip = TRIPS.find(item => item.value === tripType);
  const busOptions = useMemo(
    () =>
      data.assignments.map(assignment => {
        const bus = data.buses.find(item => item.busId === assignment.busId);
        const driver = data.drivers.find(item => item.employeeId === assignment.employeeId);
        return {
          value: String(assignment.driverRouteAssignmentId),
          label: [bus?.busNumber || `Bus ${assignment.busId}`, assignment.routeName, driver?.name]
            .filter(Boolean)
            .join(' · '),
        };
      }),
    [data]
  );
  const assignment = data.assignments.find(item => String(item.driverRouteAssignmentId) === assignmentId);

  useEffect(() => {
    if (!assignmentId && busOptions.length) setAssignmentId(busOptions[0].value);
  }, [busOptions, assignmentId]);

  useEffect(() => {
    if (!assignment) return undefined;
    let cancelled = false;
    setLoadingStudents(true);
    fetchRouteStudentsApi({
      employeeId: assignment.employeeId,
      schoolId,
      batchId,
      tripType,
      date,
      token,
    })
      .then(res => {
        if (cancelled) return;
        const list = res.data || [];
        setStudents(list);
        setStatuses(list.reduce((acc, item) => (item.status ? { ...acc, [item.studentId]: item.status } : acc), {}));
      })
      .catch(err => {
        if (cancelled) return;
        setStudents([]);
        setStatuses({});
        showWarning(formResMessage(err), 'error');
      })
      .finally(() => !cancelled && setLoadingStudents(false));
    return () => {
      cancelled = true;
    };
  }, [assignment, tripType, date, schoolId, batchId, token, showWarning]);

  // Ticking the box that is already ticked clears the student back to not marked.
  const toggle = (studentId, status) =>
    setStatuses(prev => {
      const { [studentId]: current, ...rest } = prev;
      return current === status ? rest : { ...rest, [studentId]: status };
    });
  const markAllPresent = () =>
    setStatuses(students.reduce((acc, item) => ({ ...acc, [item.studentId]: trip.present }), {}));

  const marked = students.filter(item => statuses[item.studentId]);
  const presentCount = marked.filter(item => statuses[item.studentId] !== 'ABSENT').length;
  const absentCount = marked.length - presentCount;

  const save = () => {
    if (!marked.length) return;
    setSaving(true);
    markBusAttendanceApi({
      token,
      postData: {
        employeeId: assignment.employeeId,
        schoolId,
        batchId,
        tripType,
        attendanceDate: date,
        students: marked.map(item => ({ studentId: item.studentId, status: statuses[item.studentId] })),
      },
    })
      .then(() => showWarning(`${trip.value === 'PICKUP' ? 'Pickup' : 'Drop'} attendance saved`, 'success'))
      .catch(err => showWarning(formResMessage(err), 'error'))
      .finally(() => setSaving(false));
  };

  if (!schoolId) {
    return (
      <div className="content">
        <div style={{ textAlign: 'center', color: '#9a9a9a', padding: 40 }}>Please select a school.</div>
      </div>
    );
  }

  return (
    <div className="content">
      <Paper square style={{ padding: 16, marginBottom: 16 }}>
        <Row>
          <Col lg={5} md={6} xs={12} className="mb-2">
            <Label className="form-label">Bus</Label>
            <CustomSelect
              noLabel
              usePortal
              name="bus"
              value={assignmentId}
              options={busOptions}
              placeholder={isLoading ? 'Loading buses...' : 'No bus has a driver assigned'}
              onChange={(n, v) => setAssignmentId(v)}
            />
          </Col>
          <Col lg={3} md={6} xs={12} className="mb-2">
            <Label className="form-label">Trip</Label>
            <CustomSelect
              noLabel
              usePortal
              name="trip"
              value={tripType}
              options={TRIPS}
              onChange={(n, v) => setTripType(v)}
            />
          </Col>
          <Col lg={2} md={6} xs={12} className="mb-2">
            <Label className="form-label">Date</Label>
            <input
              className="form-control"
              style={{ height: 38 }}
              type="date"
              value={date}
              onChange={e => e.target.value && setDate(e.target.value)}
            />
          </Col>
        </Row>
      </Paper>

      {isLoading || loadingStudents ? (
        <Paper square style={{ padding: 16 }}>
          <SkeletonRows rows={6} />
        </Paper>
      ) : !assignment ? (
        <Paper square style={{ padding: 16 }}>
          <EmptyState
            icon="fas fa-bus"
            title="No bus to mark"
            subtitle="Put a driver on a bus for a route in Bus assignment first."
          />
        </Paper>
      ) : (
        <>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 16 }}>
            <StatTile label="Students on the route" value={students.length} />
            <StatTile label={trip.presentLabel} value={presentCount} tone="good" />
            <StatTile label="Absent" value={absentCount} tone={absentCount ? 'bad' : 'neutral'} />
            <StatTile
              label="Not marked"
              value={students.length - marked.length}
              tone={students.length - marked.length ? 'warn' : 'neutral'}
            />
          </div>
          <Paper square style={{ padding: 16 }}>
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                flexWrap: 'wrap',
                gap: 8,
                marginBottom: 8,
              }}>
              <b style={{ color: colors.accentDark }}>{assignment.routeName}</b>
              <div style={{ display: 'flex', gap: 8 }}>
                <CustomButton
                  size="small"
                  variant="outlined"
                  name={`Mark all ${trip.presentLabel.toLowerCase()}`}
                  disabled={!students.length}
                  onClick={markAllPresent}
                />
                <CustomButton
                  size="small"
                  name="Save"
                  disabled={saving || !marked.length}
                  loading={saving}
                  showLoader
                  onClick={save}
                />
              </div>
            </div>
            {students.length ? (
              students.map(item => {
                const status = statuses[item.studentId];
                return (
                  <div
                    key={item.studentId}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      gap: 12,
                      flexWrap: 'wrap',
                      padding: '10px 4px',
                      borderTop: '1px solid #eef0f3',
                      borderLeft: `3px solid ${status ? STATUS_COLORS[status] : 'transparent'}`,
                      paddingLeft: 10,
                    }}>
                    <div style={{ minWidth: 0 }}>
                      <div style={{ fontWeight: 'bold' }}>{item.studentName}</div>
                      <small className="text-muted">
                        {[item.registerNumber, item.courseName, item.areaName].filter(Boolean).join(' · ') || '--'}
                      </small>
                    </div>
                    <div style={{ display: 'flex', gap: 8 }}>
                      <TickBox
                        label={trip.presentLabel}
                        color={STATUS_COLORS[trip.present]}
                        checked={status === trip.present}
                        onChange={() => toggle(item.studentId, trip.present)}
                      />
                      <TickBox
                        label="Absent"
                        color={STATUS_COLORS.ABSENT}
                        checked={status === 'ABSENT'}
                        onChange={() => toggle(item.studentId, 'ABSENT')}
                      />
                    </div>
                  </div>
                );
              })
            ) : (
              <EmptyState
                compact
                bare
                icon="fas fa-user-graduate"
                title="No students on this route"
                subtitle="Add the students who ride it in Bus assignment."
              />
            )}
          </Paper>
        </>
      )}
    </div>
  );
};

export default BusAttendancePage;
