import React from 'react';
import SchoolIcon from '@material-ui/icons/School';
import colors from 'config/colors';
import { orderStops } from '../transportUtils';

const MAX_VISIBLE_STOPS = 5;
const NODE = 26;

// A route drawn as a stepper in the direction of a run (see `direction` below; the backend keeps no stop sequence of its own): a numbered node on a line, the stop's name and its distance under it. The last stop is filled. Only the first
// few stops are drawn; the rest collapse into a "+N more" node (onShowAll) so a long route can't stretch its row. A narrow
// screen scrolls the stepper sideways instead of breaking the line.
const Step = ({ first, last, title, node, label, sub }) => (
  <div
    title={title}
    style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: 116, flex: '0 0 auto' }}>
    <div style={{ display: 'flex', alignItems: 'center', width: '100%' }}>
      <div style={{ flex: 1, height: 2, background: first ? 'transparent' : `${colors.accent}55` }} />
      {node}
      <div style={{ flex: 1, height: 2, background: last ? 'transparent' : `${colors.accent}55` }} />
    </div>
    <div
      style={{
        marginTop: 4,
        width: 104,
        textAlign: 'center',
        fontSize: 12,
        fontWeight: 600,
        color: colors.grey1,
        lineHeight: 1.25,
        // a long stop name wraps inside its own column (two lines, then ...) so neighbours never run into each other
        overflowWrap: 'anywhere',
        display: '-webkit-box',
        WebkitLineClamp: 2,
        WebkitBoxOrient: 'vertical',
        overflow: 'hidden',
      }}>
      {label}
    </div>
    {sub && <div style={{ fontSize: 11, color: colors.grey3 }}>{sub}</div>}
  </div>
);

const circle = (style, content) => (
  <div
    style={{
      width: NODE,
      height: NODE,
      borderRadius: '50%',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontSize: 12,
      fontWeight: 'bold',
      flexShrink: 0,
      ...style,
    }}>
    {content}
  </div>
);

// direction: 'PICKUP' is the morning run (the farthest stop first, ending at the school); 'DROP' is the evening run (leaving
// the school, the nearest stop first). The stops themselves are only ordered by distance from the school.
const RouteStopsTimeline = ({ areas, onShowAll, direction = 'PICKUP' }) => {
  const nearestFirst = orderStops(areas);
  if (!nearestFirst.length) return null;
  const isPickup = direction === 'PICKUP';
  const allStops = isPickup ? [...nearestFirst].reverse() : nearestFirst;
  const stops = allStops.slice(0, MAX_VISIBLE_STOPS);
  const hidden = allStops.length - stops.length;

  const schoolStep = at => (
    <Step
      key="school"
      first={at === 'start'}
      last={at === 'end'}
      title="School"
      node={circle({ background: colors.accentDark, color: '#fff' }, <SchoolIcon style={{ fontSize: 16 }} />)}
      label="School"
    />
  );
  const stopSteps = stops.map((stop, index) => {
    // the run's last stop is filled (the school ends a pickup, so only a drop ends on a stop)
    const isEnd = !isPickup && index === stops.length - 1 && hidden === 0;
    return (
      <Step
        key={stop.transportAreaId}
        first={isPickup && index === 0}
        last={isEnd}
        title={`Stop ${index + 1}: ${stop.areaName}${
          stop.distance != null ? ` (${stop.distance} km from school)` : ''
        }`}
        node={circle(
          isEnd
            ? { background: colors.accent, color: '#fff', border: `2px solid ${colors.accent}` }
            : { background: `${colors.accent}14`, color: colors.accent, border: `2px solid ${colors.accent}` },
          index + 1
        )}
        label={stop.areaName}
        sub={stop.distance != null ? `${stop.distance} km` : null}
      />
    );
  });
  const moreStep =
    hidden > 0 ? (
      <Step
        key="more"
        last={!isPickup}
        title="See all stops"
        node={
          <a
            href="#stops"
            onClick={e => {
              e.preventDefault();
              onShowAll();
            }}>
            {circle(
              { background: '#fff', color: colors.accent, border: `2px dashed ${colors.accent}`, fontSize: 11 },
              `+${hidden}`
            )}
          </a>
        }
        label="more"
      />
    ) : null;

  return (
    <div style={{ display: 'flex', alignItems: 'flex-start', overflowX: 'auto', marginTop: 10, paddingBottom: 2 }}>
      {isPickup ? [...stopSteps, moreStep, schoolStep('end')] : [schoolStep('start'), ...stopSteps, moreStep]}
    </div>
  );
};

export default RouteStopsTimeline;
