import React from 'react';
import { useRef, useState } from 'react';
import { Row, Col } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import MuiTable from 'views/admin/Common/MuiTable';
import { CommonLoader } from 'views/admin/Common/Loader';
import TransportGroupFormModal from 'views/admin/Fees/components/TransportGroupFormModal';
import { formResMessage } from 'utils/commonFunc';
import {
  addTransportGroupService,
  assertRouteNameFree,
  deleteTransportGroupService,
  fetchTransportAreasPlainService,
} from 'actions/admin/transportFee';
import {
  selectRouteApi,
  unassignRouteApi,
  fetchSchoolBatchStudentTransportApi,
  syncRouteStopNames,
} from 'actions/admin/transport';
import colors from 'config/colors';
import AssignBusDriverModal from './AssignBusDriverModal';
import NoteBox from 'views/admin/Common/NoteBox';
import RouteStopsModal from './RouteStopsModal';
import RouteStudentsModal from './RouteStudentsModal';
import FixStopNamesModal from './FixStopNamesModal';
import RouteStopsTimeline from './RouteStopsTimeline';
import UnassignButton from './UnassignButton';
import TransportCountCard from './TransportCountCard';

const SYNC_NOTE = (
  <NoteBox>
    These routes are the same as Fees &gt; Transport Fee. A route or destination added here also shows there, and one
    added there shows here.
  </NoteBox>
);

// Routes are the school's transport fee structures for the selected batch (the same records as
// Fees > Transport Fee). Each row ties together everything for a route: its stops, the students
// riding it, and the bus + driver assigned to it. Bus/driver/student-count figures are read-only
// summaries; each has its own button to change it.
// One component for three views of the Transport setup, each showing only what that view is about: `view` is 'routes'
// (the Routes & stops page), 'assign' (Bus assignment > Driver to bus) or 'students' (Bus assignment > Students to bus).
// They share the data and the dialogs, so a change made in one is visible in the others at once.

const RoutesTab = ({
  view = 'routes',
  assignmentFilter = null,
  onClearFilter,
  schoolId,
  batchId,
  loggedUserToken,
  showWarning,
  routes,
  areasByRoute,
  studentsByRoute,
  takenStudentIds,
  assignments,
  buses,
  drivers,
  routesById,
  busesById,
  driversById,
  isLoading,
  reload,
  refreshAssignments,
}) => {
  // Which run the stops are drawn for: the morning pickup (homes -> school) or the evening drop (school -> homes). Remembered.
  const [direction, setDirectionState] = useState(() => {
    try {
      return window.localStorage.getItem('transportRouteDirection') === 'DROP' ? 'DROP' : 'PICKUP';
    } catch (e) {
      return 'PICKUP';
    }
  });
  const setDirection = value => {
    setDirectionState(value);
    try {
      window.localStorage.setItem('transportRouteDirection', value);
    } catch (e) {
      // not remembered; the choice still applies on this page
    }
  };
  const [isRouteFormOpen, setIsRouteFormOpen] = useState(false);
  const [assignRoute, setAssignRoute] = useState(null);
  // The bus and driver being modified (null when a new one is being added to the route).
  const [modifyAssignment, setModifyAssignment] = useState(null);
  const [savingAssign, setSavingAssign] = useState(false);
  const [stopsRouteId, setStopsRouteId] = useState(null);
  const [studentsRouteId, setStudentsRouteId] = useState(null);
  // The stop-name fix waits for a "yes": the route and the stops that would be renamed are held here while the dialog asks.
  const [fix, setFix] = useState(null); // { route, stops } | null
  const [fixing, setFixing] = useState(false);
  // Add Bus & Driver waits for a "yes" the same way when stops would be renamed: the choice and those stops are held here.
  const [pendingAssign, setPendingAssign] = useState(null); // { route, stops, employeeId, busId } | null

  // The route is the Fees > Transport Fee group (same record), so it shows up there too. The new route's
  // id is kept so its Stops dialog can open straight away: a route is only useful once it has stops.
  const newRouteIdRef = useRef(null);
  const addRoute = data =>
    assertRouteNameFree({ schoolId, batchId, description: data.description, token: loggedUserToken })
      .then(() => addTransportGroupService({ token: loggedUserToken, postData: { ...data, schoolId, batchId } })())
      .then(res => {
        newRouteIdRef.current = res?.data?.transportFeeStructId || null;
        return res;
      });

  const handleRouteSaved = () => {
    setIsRouteFormOpen(false);
    showWarning('Route added. Now add the destinations it serves.', 'success');
    reload();
    if (newRouteIdRef.current) setStopsRouteId(newRouteIdRef.current);
    newRouteIdRef.current = null;
  };

  // Stops whose route name differs from their route's can't reach the driver (see syncRouteStopNames). Nothing is changed
  // here: this reads the stops fresh and opens a dialog listing exactly what would be renamed.
  const askToFixStopNames = async route => {
    try {
      const freshAreas = await fetchTransportAreasPlainService(route.transportFeeStructId, loggedUserToken);
      const stops = (freshAreas || []).filter(area => area.ruteName !== route.description);
      if (!stops.length) {
        showWarning('Nothing to fix', 'success');
        reload();
        return;
      }
      setFix({ route, stops });
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
  };

  // After the "yes": the stops are read again (they may have changed while the dialog was open) and then renamed.
  const confirmFixStopNames = async () => {
    setFixing(true);
    try {
      const freshAreas = await fetchTransportAreasPlainService(fix.route.transportFeeStructId, loggedUserToken);
      const fixed = await syncRouteStopNames({ route: fix.route, areas: freshAreas, token: loggedUserToken });
      showWarning(fixed ? `${fixed} stop(s) updated to "${fix.route.description}"` : 'Nothing to fix', 'success');
      setFix(null);
      reload();
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
    setFixing(false);
  };

  // The bus and driver are saved against the route. The driver finds the route's students through the stops' route name,
  // so every stop is made to carry the route's current name first (a no-op when they already do).
  const assignBusDriver = async ({ route, employeeId, busId, replaces }) => {
    const freshAreas = await fetchTransportAreasPlainService(route.transportFeeStructId, loggedUserToken);
    const fixed = await syncRouteStopNames({ route, areas: freshAreas, token: loggedUserToken });
    await selectRouteApi({
      postData: {
        employeeId,
        busId,
        transportFeeStructId: route.transportFeeStructId,
        routeName: route.description,
        schoolId,
        batchId,
      },
      token: loggedUserToken,
    });
    // Modifying to another driver: the new driver is on the route now, so the old one is taken off it.
    if (replaces && replaces.employeeId !== employeeId) {
      await unassignRouteApi({ driverRouteAssignmentId: replaces.driverRouteAssignmentId, token: loggedUserToken });
    }
    showWarning(
      replaces
        ? 'Bus and driver updated successfully'
        : fixed
        ? `Bus and driver assigned. ${fixed} stop(s) renamed to match the route.`
        : 'Bus and driver assigned successfully',
      'success'
    );
    setPendingAssign(null);
    setAssignRoute(null);
    setModifyAssignment(null);
    reload();
  };

  // Save in the Add Bus & Driver dialog. If any stop would have to be renamed to make the assignment work, nothing is saved
  // yet: the dialog below lists those stops and the assignment waits for a "yes" (confirmAssignWithRename).
  const handleAssign = async ({ employeeId, busId }) => {
    setSavingAssign(true);
    try {
      const freshAreas = await fetchTransportAreasPlainService(assignRoute.transportFeeStructId, loggedUserToken);
      const stops = (freshAreas || []).filter(area => area.ruteName !== assignRoute.description);
      if (stops.length) {
        setPendingAssign({ route: assignRoute, stops, employeeId, busId, replaces: modifyAssignment });
      } else {
        await assignBusDriver({ route: assignRoute, employeeId, busId, replaces: modifyAssignment });
      }
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
    setSavingAssign(false);
  };

  const confirmAssignWithRename = async () => {
    setSavingAssign(true);
    try {
      await assignBusDriver(pendingAssign);
    } catch (err) {
      setPendingAssign(null);
      showWarning(formResMessage(err), 'error');
    }
    setSavingAssign(false);
  };

  // The backend doesn't guard route deletion, so check here that nothing is left hanging off it.
  // Checked live (assignments, stops and students are read again), not against what the page loaded earlier.
  const handleDelete = async transportFeeStructId => {
    try {
      const [current, freshAreas, studentRes] = await Promise.all([
        refreshAssignments(),
        fetchTransportAreasPlainService(transportFeeStructId, loggedUserToken),
        fetchSchoolBatchStudentTransportApi({ schoolId, batchId, token: loggedUserToken }),
      ]);
      const students = (studentRes.data || []).filter(st => st.transportFeeStructId === transportFeeStructId).length;
      if (current.some(a => a.transportFeeStructId === transportFeeStructId)) {
        showWarning('This route has a bus and driver assigned. Unassign them first, then delete the route.', 'error');
      } else if (students) {
        showWarning(`Remove the ${students} student(s) from this route first.`, 'error');
      } else if ((freshAreas || []).length) {
        showWarning("Delete this route's stops first.", 'error');
      } else {
        await deleteTransportGroupService({ transportFeeStructId, token: loggedUserToken })();
        showWarning('Route deleted successfully', 'success');
        reload();
      }
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
  };

  // Coming from a bus or a driver's "View assignment": only the routes that bus or driver is on.
  const filtered = view === 'assign' && !!(assignmentFilter?.busId || assignmentFilter?.driverId);
  const visibleRoutes = filtered
    ? routes.filter(route =>
        assignments.some(
          a =>
            a.transportFeeStructId === route.transportFeeStructId &&
            (assignmentFilter.busId ? a.busId === assignmentFilter.busId : a.employeeId === assignmentFilter.driverId)
        )
      )
    : routes;
  const filterName = assignmentFilter?.busId
    ? `bus ${busesById[assignmentFilter.busId]?.busNumber || ''}`
    : `driver ${driversById[assignmentFilter?.driverId]?.name || ''}`;

  const rows = visibleRoutes.map(route => {
    const id = route.transportFeeStructId;
    const routeAssignments = assignments.filter(a => a.transportFeeStructId === id);
    const stops = (areasByRoute[id] || []).length;
    // Students are matched to the driver by the stop's route name, so a stop whose name differs is skipped.
    const mismatched = (areasByRoute[id] || []).filter(a => a.ruteName !== route.description).length;
    const studentCount = (studentsByRoute[id] || []).length;
    const totalSeats = routeAssignments.reduce((sum, a) => sum + (busesById[a.busId]?.seatingCapacity || 0), 0);
    const overCapacity = totalSeats > 0 && studentCount > totalSeats;
    const isRoutesView = view === 'routes';
    return {
      ...route,
      routeLabel: (
        <span>
          <div>{route.description}</div>
          <div
            style={{
              fontSize: 12,
              color: overCapacity ? '#c62828' : '#7d7d7d',
              fontWeight: overCapacity ? 'bold' : 'normal',
            }}>
            {`${stops} stop(s) · ${studentCount} student(s)`}
            {overCapacity ? ` (buses seat ${totalSeats})` : ''}
          </div>
          {isRoutesView && !!mismatched && (
            <div style={{ fontSize: 12, color: '#e65100' }}>
              {`${mismatched} stop(s) have a different route name, so their students won't show for the driver. `}
              <a
                href="#fix"
                onClick={e => {
                  e.preventDefault();
                  askToFixStopNames(route);
                }}>
                Fix now
              </a>
            </div>
          )}
          {isRoutesView && (
            <RouteStopsTimeline areas={areasByRoute[id]} direction={direction} onShowAll={() => setStopsRouteId(id)} />
          )}
        </span>
      ),
      busesDriversLabel: routeAssignments.length ? (
        routeAssignments.map(a => {
          const driver = driversById[a.employeeId];
          return (
            <div key={a.driverRouteAssignmentId} style={{ marginBottom: 8 }}>
              <div>
                <b>{busesById[a.busId]?.busNumber || '--'}</b>
              </div>
              <div style={{ fontSize: 13, color: '#5e6977', marginTop: 2 }}>
                {driver?.name || '--'}
                {driver?.phoneNumber && (
                  <>
                    {' - '}
                    <a href={`tel:${driver.phoneNumber}`} style={{ color: 'inherit' }}>
                      {driver.phoneNumber}
                    </a>
                  </>
                )}
              </div>
            </div>
          );
        })
      ) : (
        <span
          style={{
            color: view === 'assign' ? '#e65100' : '#9a9a9a',
            fontWeight: view === 'assign' ? 'bold' : 'normal',
          }}>
          {view === 'assign' ? 'Needs a bus and driver' : 'Unassigned'}
        </span>
      ),
      studentsLabel: (
        <span>
          <b>{studentCount}</b> student(s)
          {totalSeats > 0 && (
            <div
              style={{
                fontSize: 12,
                color: overCapacity ? '#c62828' : '#7d7d7d',
              }}>{`${totalSeats} seat(s) on the bus`}</div>
          )}
        </span>
      ),
    };
  });

  if (!batchId) {
    return (
      <div style={{ textAlign: 'center', color: '#9a9a9a', padding: 40 }}>
        Routes belong to an academic year. Please select a batch first.
      </div>
    );
  }
  if (isLoading) return <CommonLoader />;

  const stopsRoute = routesById[stopsRouteId];
  const studentsRoute = routesById[studentsRouteId];

  const tableConfig = {
    routes: { headers: ['Route', 'Buses & Drivers', 'Action'], columns: ['routeLabel', 'busesDriversLabel', 'action'] },
    assign: { headers: ['Route', 'Bus & Driver', 'Action'], columns: ['routeLabel', 'busesDriversLabel', 'action'] },
    students: {
      headers: ['Route', 'Bus & Driver', 'Students', 'Action'],
      columns: ['routeLabel', 'busesDriversLabel', 'studentsLabel', 'action'],
    },
  }[view];

  return (
    <>
      {view !== 'assign' && (
        <TransportCountCard
          schoolId={schoolId}
          batchId={batchId}
          token={loggedUserToken}
          refreshKey={Object.values(studentsByRoute || {}).reduce((total, list) => total + list.length, 0)}
        />
      )}
      {view === 'routes' && (
        <Row className="mb-2" style={{ alignItems: 'center' }}>
          <Col>
            <div style={{ display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: 10 }}>
              <div
                role="tablist"
                style={{
                  display: 'inline-flex',
                  padding: 3,
                  borderRadius: 20,
                  background: colors.sidebarActiveItemBg,
                }}>
                {[
                  { key: 'PICKUP', label: 'Morning pickup' },
                  { key: 'DROP', label: 'Evening drop' },
                ].map(option => (
                  <button
                    key={option.key}
                    type="button"
                    role="tab"
                    aria-selected={direction === option.key}
                    onClick={() => setDirection(option.key)}
                    style={{
                      border: 0,
                      borderRadius: 17,
                      padding: '5px 16px',
                      fontSize: 13,
                      fontWeight: 'bold',
                      cursor: 'pointer',
                      color: direction === option.key ? colors.accent : colors.accentDark,
                      opacity: direction === option.key ? 1 : 0.75,
                      background: direction === option.key ? '#fff' : 'transparent',
                      boxShadow: direction === option.key ? '0 1px 4px rgba(91,21,132,0.25)' : 'none',
                    }}>
                    {option.label}
                  </button>
                ))}
              </div>
              <span style={{ fontSize: 12, color: colors.grey3 }}>
                {direction === 'PICKUP'
                  ? 'Students are picked up at the farthest stop first and the bus ends at the school.'
                  : 'The bus leaves the school and drops students at the nearest stop first.'}
              </span>
            </div>
          </Col>
          <Col xs="auto" style={{ textAlign: 'right' }}>
            <CustomButton
              size="small"
              name="+ Add Route"
              onClick={() => setIsRouteFormOpen(true)}
              style={{ backgroundColor: colors.accent, color: colors.white }}
            />
          </Col>
        </Row>
      )}
      {filtered && (
        <div style={{ fontSize: 13, marginBottom: 10 }}>
          Showing the routes of <b>{filterName}</b>.{' '}
          <a
            href="#all"
            onClick={e => {
              e.preventDefault();
              onClearFilter();
            }}>
            Show all routes
          </a>
        </div>
      )}
      {!rows.length && (
        <div style={{ textAlign: 'center', color: '#9a9a9a', padding: 30 }}>
          {filtered
            ? `${filterName} is not on any route yet. Use Assign bus & driver on a route to put it on one.`
            : 'No routes yet. Add a route and its stops on the Routes & stops page first.'}
        </div>
      )}
      <MuiTable
        tableHeaders={tableConfig.headers}
        tableBodyData={{ content: rows }}
        bodyColumns={tableConfig.columns}
        idName="transportFeeStructId"
        dropDownActions={view === 'routes' ? ['delete'] : []}
        deleteItem={handleDelete}
        hidePagination={true}
        renderRowExtra={route => (
          <>
            {view === 'assign' && (
              <>
                {assignments.filter(a => a.transportFeeStructId === route.transportFeeStructId).length === 0 && (
                  <CustomButton
                    size="small"
                    variant="outlined"
                    onClick={() => {
                      setModifyAssignment(null);
                      setAssignRoute(routesById[route.transportFeeStructId]);
                    }}
                    name="Assign bus & driver"
                  />
                )}
                {assignments
                  .filter(a => a.transportFeeStructId === route.transportFeeStructId)
                  .map(a => (
                    <div key={a.driverRouteAssignmentId} style={{ display: 'flex', gap: 6, marginBottom: 6 }}>
                      <CustomButton
                        size="small"
                        variant="outlined"
                        name="Modify"
                        onClick={() => {
                          setModifyAssignment(a);
                          setAssignRoute(routesById[route.transportFeeStructId]);
                        }}
                      />
                      <UnassignButton
                        assignment={a}
                        driverName={driversById[a.employeeId]?.name}
                        busNumber={busesById[a.busId]?.busNumber}
                        routeName={route.description}
                        loggedUserToken={loggedUserToken}
                        showWarning={showWarning}
                        onDone={reload}
                      />
                    </div>
                  ))}
                {assignments.some(a => a.transportFeeStructId === route.transportFeeStructId) && (
                  <a
                    href="#add-another"
                    style={{ fontSize: 12, color: colors.accent, fontWeight: 'bold' }}
                    onClick={e => {
                      e.preventDefault();
                      setModifyAssignment(null);
                      setAssignRoute(routesById[route.transportFeeStructId]);
                    }}>
                    + Add another bus &amp; driver
                  </a>
                )}
              </>
            )}
            {view === 'routes' && (
              <CustomButton
                size="small"
                variant="outlined"
                onClick={() => setStopsRouteId(route.transportFeeStructId)}
                name="Stops"
              />
            )}
            {view === 'students' && (
              <CustomButton
                size="small"
                variant="outlined"
                onClick={() => setStudentsRouteId(route.transportFeeStructId)}
                name="Manage students"
              />
            )}
          </>
        )}
      />
      <TransportGroupFormModal
        isModalOpen={isRouteFormOpen}
        formModalCloseProp={() => setIsRouteFormOpen(false)}
        addTransportGroup={addRoute}
        note={SYNC_NOTE}
        existingRoutes={routes}
        onSuccess={handleRouteSaved}
      />
      <AssignBusDriverModal
        isOpen={!!assignRoute}
        route={assignRoute}
        assignment={modifyAssignment}
        buses={buses}
        drivers={drivers}
        assignments={assignments}
        routesById={routesById}
        stopsCount={assignRoute ? (areasByRoute[assignRoute.transportFeeStructId] || []).length : 0}
        studentsCount={assignRoute ? (studentsByRoute[assignRoute.transportFeeStructId] || []).length : 0}
        saving={savingAssign}
        onClose={() => {
          setAssignRoute(null);
          setModifyAssignment(null);
        }}
        onSave={handleAssign}
      />
      <RouteStopsModal
        isOpen={!!stopsRoute}
        route={stopsRoute}
        areas={stopsRoute ? areasByRoute[stopsRoute.transportFeeStructId] || [] : []}
        schoolId={schoolId}
        batchId={batchId}
        otherRouteAreas={routes
          .filter(route => route.transportFeeStructId !== stopsRouteId)
          .flatMap(route =>
            (areasByRoute[route.transportFeeStructId] || []).map(area => ({
              areaName: area.areaName,
              routeName: route.description,
            }))
          )}
        loggedUserToken={loggedUserToken}
        showWarning={showWarning}
        onFixNames={() => askToFixStopNames(stopsRoute)}
        onClose={() => setStopsRouteId(null)}
        onChanged={reload}
      />
      <FixStopNamesModal
        isOpen={!!fix}
        route={fix?.route}
        stops={fix?.stops || []}
        saving={fixing}
        onConfirm={confirmFixStopNames}
        onClose={() => setFix(null)}
      />
      <FixStopNamesModal
        assign
        isOpen={!!pendingAssign}
        route={pendingAssign?.route}
        stops={pendingAssign?.stops || []}
        saving={savingAssign}
        onConfirm={confirmAssignWithRename}
        onClose={() => setPendingAssign(null)}
      />
      <RouteStudentsModal
        isOpen={!!studentsRoute}
        route={studentsRoute}
        areas={studentsRoute ? areasByRoute[studentsRoute.transportFeeStructId] || [] : []}
        routeStudents={studentsRoute ? studentsByRoute[studentsRoute.transportFeeStructId] || [] : []}
        takenStudentIds={takenStudentIds}
        schoolId={schoolId}
        batchId={batchId}
        loggedUserToken={loggedUserToken}
        showWarning={showWarning}
        onClose={() => setStudentsRouteId(null)}
        onChanged={reload}
      />
    </>
  );
};

export default RoutesTab;
