import React from 'react';
import { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import { busLabel } from '../transportUtils';

// Puts a driver on a bus for one route. Any driver can be paired with any active bus - a route can
// have several driver/bus pairs and a bus can serve several routes. The one limit is the backend's:
// a driver holds a single route per batch, so picking a driver who is already on another route moves
// them here (their old assignment is replaced), which the dropdown spells out. The same bus cannot be put on the
// same route twice (with two drivers).
const AssignBusDriverModal = ({
  isOpen,
  route,
  assignment, // set when an existing bus and driver of the route is being modified
  buses,
  drivers,
  assignments,
  routesById,
  stopsCount = 0,
  studentsCount = 0,
  saving,
  onClose,
  onSave,
}) => {
  const [driverId, setDriverId] = useState(null);
  const [busId, setBusId] = useState(null);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    if (isOpen) {
      setDriverId(assignment?.employeeId || null);
      setBusId(assignment?.busId || null);
      setErrors({});
    }
  }, [isOpen, assignment]);

  const driverOptions = drivers.map(d => {
    const current = assignments.find(a => a.employeeId === d.employeeId);
    const label =
      assignment && d.employeeId === assignment.employeeId
        ? `${d.name} (current driver)`
        : current && current.transportFeeStructId === route?.transportFeeStructId
        ? `${d.name} (already on this route - changes bus)`
        : current
        ? `${d.name} (on ${
            routesById[current.transportFeeStructId]?.description || current.routeName
          } - will move here)`
        : d.name;
    return { value: d.employeeId, label };
  });

  const busOptions = buses.filter(b => b.status === 'ACTIVE').map(b => ({ value: b.busId, label: busLabel(b) }));

  const handleSubmit = () => {
    const nextErrors = {};
    if (!driverId) nextErrors.driverId = 'Pick a driver';
    if (!busId) nextErrors.busId = 'Pick a bus';
    // One bus runs a route once: a second driver on the same bus and route would put two drivers on one vehicle.
    const clash =
      busId &&
      assignments.find(
        a =>
          a.busId === busId &&
          a.transportFeeStructId === route?.transportFeeStructId &&
          a.employeeId !== driverId &&
          a.employeeId !== assignment?.employeeId
      );
    if (clash) {
      const otherDriver = drivers.find(d => d.employeeId === clash.employeeId)?.name || 'another driver';
      nextErrors.busId = `This bus already runs this route with ${otherDriver}. Pick another bus, or use Modify to change that driver.`;
    }
    setErrors(nextErrors);
    if (!Object.keys(nextErrors).length) onSave({ employeeId: driverId, busId });
  };

  return (
    <Modal size="md" isOpen={isOpen} toggle={onClose}>
      <ModalHeader toggle={onClose}>
        {assignment ? 'Modify bus & driver' : 'Assign bus & driver'} &mdash; {route?.description}
      </ModalHeader>
      <ModalBody>
        <div style={{ fontSize: 12, marginBottom: 12, color: stopsCount && studentsCount ? '#7d7d7d' : '#e65100' }}>
          {`This route has ${stopsCount} stop(s) and ${studentsCount} student(s).`}
          {!stopsCount && ' Add its stops first (Routes & stops page) so the driver has somewhere to go.'}
          {!!stopsCount && !studentsCount && ' Add students (Students to bus tab) so the driver has someone to mark.'}
        </div>
        <CustomSelect
          label="Driver"
          name="driverId"
          isRequired
          usePortal
          value={driverId}
          options={driverOptions}
          onChange={(name, value) => setDriverId(value)}
          error={errors.driverId}
        />
        {!driverOptions.length && (
          <div style={{ fontSize: 12, color: '#9a9a9a', marginTop: 4 }}>
            No drivers yet. Add one in the Drivers tab.
          </div>
        )}
        <div className="mt-3">
          <CustomSelect
            label="Bus"
            name="busId"
            isRequired
            usePortal
            value={busId}
            options={busOptions}
            onChange={(name, value) => setBusId(value)}
            error={errors.busId}
          />
        </div>
        {!busOptions.length && (
          <div style={{ fontSize: 12, color: '#9a9a9a', marginTop: 4 }}>No active bus. Add one in the Buses tab.</div>
        )}
      </ModalBody>
      <ModalFooter>
        <CustomButton
          className="mr-2"
          type="button"
          color="default"
          disabled={saving}
          onClick={onClose}
          name="Cancel"
        />
        <CustomButton
          name={assignment ? 'Save' : 'Assign'}
          disabled={saving}
          loading={saving}
          onClick={handleSubmit}
          style={{ backgroundColor: colors.accent, color: colors.white }}
        />
      </ModalFooter>
    </Modal>
  );
};

export default AssignBusDriverModal;
