import React from 'react';
import { Row, Col, Label } from 'reactstrap';
import Checkbox from '@material-ui/core/Checkbox';
import FormControlLabel from '@material-ui/core/FormControlLabel';
import Chip from '@material-ui/core/Chip';
import CustomSelect from 'components/CustomSelect';
import { CommonLoader } from '../../Common/Loader.jsx';
import { formStudentName } from 'config/constants.js';
import { toTitleCase } from 'utils/commonFunc.js';
import EmptyState from 'views/admin/Common/EmptyState';

const ALL_SCHOOL = '';

// Shared "pick one or more students" widget: class filter + search + checkbox list + a
// clear "who's selected" chip row, so non-technical users always see the current selection
// instead of having to scroll a checkbox list to remember who they picked.
const StudentPicker = ({
  courseOptions = [],
  candidateStudents = [],
  isCandidatesFetching = false,
  courseFilter,
  searchText,
  onCourseFilterChange,
  onSearchTextChange,
  selectedMap = {},
  onToggle,
  onClearAll,
  // Students already assigned elsewhere (e.g. this exact fee/concession already has them) -
  // shown checked but not interactive, so nobody has to guess whether re-checking one does
  // anything; removing an existing assignment happens from the table's own Delete action.
  disabledStudentIds = [],
}) => {
  const selectedList = Object.values(selectedMap);
  const disabledSet = new Set(disabledStudentIds);

  const selectAllVisible = () => {
    candidateStudents.forEach(student => {
      if (!disabledSet.has(student.studentId) && !selectedMap[student.studentId]) onToggle(student, true);
    });
  };

  return (
    <div>
      <Row>
        <Col md={5} sm={5} xs={12}>
          <Label htmlFor="">Filter by class</Label>
          <CustomSelect
            name="courseFilter"
            noLabel
            value={courseFilter}
            onChange={(name, val) => onCourseFilterChange(val)}
            options={[{ value: ALL_SCHOOL, label: 'All School Students' }, ...courseOptions]}
          />
        </Col>
        <Col md={7} sm={7} xs={12}>
          <Label htmlFor="">Search student</Label>
          <input
            className="form-control"
            style={{ height: 38 }}
            placeholder="Search by name or registration number"
            value={searchText}
            onChange={e => onSearchTextChange(e.target.value)}
          />
        </Col>
      </Row>

      <div style={{ marginTop: 12, marginBottom: 8 }}>
        <span style={{ fontWeight: 'bold', fontSize: 13, color: '#6b778a' }}>Selected ({selectedList.length}):</span>{' '}
        {selectedList.length ? (
          <>
            {selectedList.map(student => (
              <Chip
                key={student.studentId}
                size="small"
                label={toTitleCase(formStudentName(student))}
                onDelete={() => onToggle(student, false)}
                style={{ margin: 2 }}
              />
            ))}
            <span
              onClick={onClearAll}
              style={{ marginLeft: 8, fontSize: 12, color: '#c62828', cursor: 'pointer', textDecoration: 'underline' }}>
              Clear all
            </span>
          </>
        ) : (
          <span style={{ fontSize: 12, color: '#9a9a9a' }}>None yet &mdash; check names below to add them</span>
        )}
      </div>

      <div style={{ marginBottom: 5 }}>
        <span onClick={selectAllVisible} style={{ fontSize: 12, color: '#1565c0', cursor: 'pointer' }}>
          Select all shown below
        </span>
      </div>

      <div style={{ maxHeight: 280, overflowY: 'auto', border: '1px solid #eee', borderRadius: 6, padding: 10 }}>
        {isCandidatesFetching ? (
          <CommonLoader />
        ) : candidateStudents?.length ? (
          candidateStudents.map(student => {
            const isDisabled = disabledSet.has(student.studentId);
            return (
              <FormControlLabel
                key={student.studentId}
                style={{ display: 'flex' }}
                control={
                  <Checkbox
                    size="small"
                    checked={isDisabled || !!selectedMap[student.studentId]}
                    disabled={isDisabled}
                    onChange={e => onToggle(student, e.target.checked)}
                  />
                }
                label={
                  <span style={{ fontSize: 13, color: isDisabled ? '#9a9a9a' : undefined }}>
                    {toTitleCase(formStudentName(student))} ({student.registerNumber || student.registrationNumber})
                    {student.courseName ? ` - ${student.courseName}` : ''}
                    {isDisabled ? ' (already assigned)' : ''}
                  </span>
                }
              />
            );
          })
        ) : (
          <EmptyState compact bare icon="fas fa-user-graduate" title="No students found" />
        )}
      </div>
    </div>
  );
};

export default StudentPicker;
