import React from 'react';
import { useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import CustomButton from 'components/CustomButton';
import ConfirmModal from 'views/admin/Common/ConfirmModal';
import TransportAreaFormModal from 'views/admin/Fees/components/TransportAreaFormModal';
import { formResMessage } from 'utils/commonFunc';
import {
  addTransportAreaService,
  assertStopNamesFree,
  normalizeName,
  updateTransportAreaService,
  deleteTransportAreaService,
} from 'actions/admin/transportFee';

// Stops (destinations) of one route, with their distance and fee - the same TransportArea records
// and add/edit form the Fees > Transport Fee tab uses, so a stop added here shows up there too.
const RouteStopsModal = ({
  isOpen,
  route,
  areas,
  schoolId,
  batchId,
  otherRouteAreas,
  loggedUserToken,
  showWarning,
  onFixNames,
  onClose,
  onChanged,
}) => {
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingArea, setEditingArea] = useState(null);
  const [deleteArea, setDeleteArea] = useState(null);
  const [deleting, setDeleting] = useState(false);

  const openForm = area => {
    setEditingArea(area);
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setIsFormOpen(false);
    setEditingArea(null);
  };

  // Names are checked against the route's live stops before anything is saved (see assertStopNamesFree).
  const addAreas = async rows => {
    await assertStopNamesFree({
      transportFeeStructId: route.transportFeeStructId,
      rows,
      schoolId,
      batchId,
      token: loggedUserToken,
    });
    return Promise.all(
      rows.map(row =>
        addTransportAreaService({
          token: loggedUserToken,
          postData: { ...row, transportFeeStructId: route.transportFeeStructId },
        })()
      )
    );
  };

  const updateArea = async (transportAreaId, row) => {
    // Only a renamed destination needs checking (saving a new distance or fee must not trip over older data).
    if (normalizeName(row.areaName) !== normalizeName(editingArea?.areaName)) {
      await assertStopNamesFree({
        transportFeeStructId: route.transportFeeStructId,
        rows: [row],
        ignoreAreaId: transportAreaId,
        schoolId,
        batchId,
        token: loggedUserToken,
      });
    }
    return updateTransportAreaService({
      token: loggedUserToken,
      postData: { ...row, transportAreaId, transportFeeStructId: route.transportFeeStructId },
    })();
  };

  const handleSaved = () => {
    showWarning(editingArea ? 'Updated successfully' : 'Added successfully', 'success');
    closeForm();
    onChanged();
  };

  // The backend refuses (with a readable message) while students are still on the stop.
  const confirmDelete = async () => {
    setDeleting(true);
    try {
      await deleteTransportAreaService({ transportAreaId: deleteArea.transportAreaId, token: loggedUserToken })();
      showWarning('Deleted successfully', 'success');
      onChanged();
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
    setDeleting(false);
    setDeleteArea(null);
  };

  const headStyle = { color: '#7d7d7d', fontSize: 12 };
  // Stops saved under another route name never reach the driver, so they are flagged and fixable in one go.
  const mismatched = areas.filter(area => area.ruteName !== route?.description).length;

  return (
    <Modal size="lg" isOpen={isOpen} toggle={onClose}>
      <ModalHeader toggle={onClose}>Stops &mdash; {route?.description}</ModalHeader>
      <ModalBody>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 8 }}>
          <span style={{ fontSize: 12, color: '#e65100' }}>
            {!!mismatched &&
              `${mismatched} stop(s) are saved under another route name, so their students won't reach the driver.`}
            {!!mismatched && onFixNames && (
              <CustomButton size="small" variant="outlined" className="ml-2" name="Fix now" onClick={onFixNames} />
            )}
          </span>
          <CustomButton size="small" name="+ Add Destination" onClick={() => openForm(null)} />
        </div>
        {areas.length ? (
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell style={headStyle}>
                  <b>Destination</b>
                </TableCell>
                <TableCell style={headStyle}>
                  <b>Distance (km)</b>
                </TableCell>
                <TableCell style={headStyle}>
                  <b>Amount</b>
                </TableCell>
                <TableCell align="right" style={headStyle}>
                  <b>Action</b>
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {areas.map(area => (
                <TableRow key={area.transportAreaId}>
                  <TableCell>
                    {area.areaName}
                    {area.ruteName !== route?.description && (
                      <div style={{ fontSize: 11, color: '#e65100' }}>
                        Saved under route name &quot;{area.ruteName}&quot;
                      </div>
                    )}
                  </TableCell>
                  <TableCell>{area.distance ?? 'N/A'}</TableCell>
                  <TableCell>{`₹${area.amount}`}</TableCell>
                  <TableCell align="right">
                    <CustomButton
                      size="small"
                      variant="outlined"
                      color="default"
                      className="mr-2"
                      name="Edit"
                      onClick={() => openForm(area)}
                    />
                    <CustomButton
                      size="small"
                      variant="outlined"
                      color="default"
                      style={{ color: '#c62828', borderColor: '#c62828' }}
                      name="Delete"
                      onClick={() => setDeleteArea(area)}
                    />
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div style={{ textAlign: 'center', padding: 20, fontSize: 13, color: '#9a9a9a' }}>
            No stops yet. Add the destinations this route serves.
          </div>
        )}
      </ModalBody>
      <ModalFooter>
        <CustomButton type="button" color="default" onClick={onClose} name="Close" />
      </ModalFooter>
      <TransportAreaFormModal
        groupName={route?.description}
        isModalOpen={isFormOpen}
        formModalCloseProp={closeForm}
        addTransportArea={addAreas}
        onSuccess={handleSaved}
        editingArea={editingArea}
        existingAreaNames={areas.map(area => area.areaName)}
        otherRouteAreas={otherRouteAreas}
        onUpdate={updateArea}
      />
      <ConfirmModal
        confirmModalOpen={!!deleteArea}
        confirmMessage={`Delete destination ${deleteArea?.areaName}?`}
        loading={deleting}
        deleteConfirm={confirmDelete}
        deleteCancel={() => setDeleteArea(null)}
      />
    </Modal>
  );
};

export default RouteStopsModal;
