import React from 'react';
import { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col } from 'reactstrap';
import moment from 'moment';
import validator from 'validator';
import CustomInput from 'views/admin/Common/CustomInput';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import { formResMessage, toLoginEmail } from 'utils/commonFunc';
import DateField from './DateField';
import { toDateString } from '../transportUtils';

const MIN_DRIVER_AGE = 18;

const GENDER_OPTIONS = [
  { label: 'Male', value: 'MALE' },
  { label: 'Female', value: 'FEMALE' },
];

const emptyForm = {
  name: '',
  email: '',
  phoneNumber: '',
  gender: null,
  dateOfBirth: '',
  joiningDateTime: '',
  qualification: '',
  totalExperience: '',
};

const validate = (data, isEditing) => {
  const errors = {};
  const name = data.name?.trim();
  if (!name) errors.name = 'Name cannot be empty';
  else if (name.length < 3) errors.name = 'Name must be at least 3 characters';
  if (!isEditing) {
    if (!data.email?.trim()) errors.email = 'Email cannot be empty';
    else if (!validator.isEmail(toLoginEmail(data.email))) errors.email = 'Invalid email';
  }
  if (!data.phoneNumber?.trim()) errors.phoneNumber = 'Phone number cannot be empty';
  else if (!validator.isMobilePhone(data.phoneNumber.trim())) errors.phoneNumber = 'Invalid phone number';
  if (!data.gender) errors.gender = 'Gender cannot be empty';
  if (data.dateOfBirth && moment(data.dateOfBirth) > moment().subtract(MIN_DRIVER_AGE, 'years')) {
    errors.dateOfBirth = `Minimum age should be ${MIN_DRIVER_AGE}`;
  }
  if (data.dateOfBirth && data.joiningDateTime && moment(data.joiningDateTime) <= moment(data.dateOfBirth)) {
    errors.joiningDateTime = "Joining date shouldn't be on or before the date of birth";
  }
  return errors;
};

// Same employee record the School Staffs forms create, just pinned to a non-teaching "Driver" in
// the Transport department - so a driver shows up in staff attendance/payroll like any other
// worker. The form edits `editDriver` in place on update (email, code etc. are left as they were).
const DriverFormModal = ({ isOpen, editDriver, saving, onClose, onSave }) => {
  const [data, setData] = useState(emptyForm);
  const [errors, setErrors] = useState({});
  const isEditing = !!editDriver;

  useEffect(() => {
    if (isOpen) {
      setData(
        editDriver
          ? {
              name: editDriver.name || '',
              email: editDriver.email || '',
              phoneNumber: editDriver.phoneNumber || '',
              gender: editDriver.gender || null,
              dateOfBirth: toDateString(editDriver.dateOfBirth),
              joiningDateTime: toDateString(editDriver.joiningDateTime),
              qualification: editDriver.qualification || '',
              totalExperience: editDriver.totalExperience || '',
            }
          : emptyForm
      );
      setErrors({});
    }
  }, [isOpen]);

  const handleChange = (name, value) => setData(prev => ({ ...prev, [name]: value }));

  const handleSubmit = e => {
    e.preventDefault();
    const nextErrors = validate(data, isEditing);
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length) return;
    // The employee API takes dates as epoch millis, same as the other employee forms.
    const asMillis = value => (value ? moment(value).valueOf() : null);
    onSave({
      name: data.name.trim(),
      email: toLoginEmail(data.email),
      phoneNumber: data.phoneNumber.trim(),
      gender: data.gender,
      dateOfBirth: asMillis(data.dateOfBirth),
      joiningDateTime: asMillis(data.joiningDateTime),
      qualification: data.qualification.trim() || null,
      totalExperience: data.totalExperience.trim() || null,
    }).catch(err => setErrors({ global: formResMessage(err) }));
  };

  return (
    <Modal size="lg" isOpen={isOpen} toggle={onClose}>
      <form onSubmit={handleSubmit}>
        <ModalHeader toggle={onClose}>
          <span style={{ whiteSpace: 'nowrap' }}>{isEditing ? 'UPDATE DRIVER' : 'ADD DRIVER'}</span>
        </ModalHeader>
        <ModalBody>
          {errors.global && <div className="mb-3 alert alert-danger">{errors.global}</div>}
          <Row>
            <Col sm={6}>
              <CustomInput
                label={
                  <>
                    Name<sup> *</sup>
                  </>
                }
                name="name"
                value={data.name}
                onChange={handleChange}
                error={errors.name}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label={
                  <>
                    Username or Email<sup> *</sup>
                  </>
                }
                name="email"
                value={data.email}
                disabled={isEditing}
                onChange={handleChange}
                error={errors.email}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label={
                  <>
                    Phone number<sup> *</sup>
                  </>
                }
                name="phoneNumber"
                placeholder="E.g: +91-9876... or 98765..."
                value={data.phoneNumber}
                onChange={handleChange}
                error={errors.phoneNumber}
              />
            </Col>
            <Col sm={6}>
              <CustomSelect
                label="Gender"
                name="gender"
                isRequired
                usePortal
                value={data.gender}
                options={GENDER_OPTIONS}
                onChange={handleChange}
                error={errors.gender}
              />
            </Col>
            <Col sm={6}>
              <DateField
                label="Date of Birth"
                name="dateOfBirth"
                value={data.dateOfBirth}
                onChange={handleChange}
                error={errors.dateOfBirth}
                maxDate={moment().subtract(MIN_DRIVER_AGE, 'years').toDate()}
              />
            </Col>
            <Col sm={6}>
              <DateField
                label="Joining Date"
                name="joiningDateTime"
                value={data.joiningDateTime}
                onChange={handleChange}
                error={errors.joiningDateTime}
                maxDate={new Date()}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Qualification"
                name="qualification"
                placeholder="E.g: 10th, HSC"
                value={data.qualification}
                onChange={handleChange}
              />
            </Col>
            <Col sm={6}>
              <CustomInput
                label="Driving experience"
                name="totalExperience"
                placeholder="E.g: 5 years"
                value={data.totalExperience}
                onChange={handleChange}
              />
            </Col>
          </Row>
          {!isEditing && (
            <div style={{ fontSize: 12, color: '#9a9a9a' }}>
              A login is created for the driver with this email as the username and the school&apos;s default password.
            </div>
          )}
        </ModalBody>
        <ModalFooter>
          <CustomButton
            className="mr-2"
            type="button"
            color="default"
            disabled={saving}
            onClick={onClose}
            name="Cancel"
          />
          <CustomButton
            type="submit"
            name="Save"
            disabled={saving}
            loading={saving}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default DriverFormModal;
