import React from 'react';
import { useState } from 'react';
import { Row, Col } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import MuiTable from 'views/admin/Common/MuiTable';
import { CommonLoader } from 'views/admin/Common/Loader';
import { ActiveSpan, DeactiveSpan } from 'views/admin/Common/StatusBadges';
import { formResMessage } from 'utils/commonFunc';
import { saveBusApi, updateBusApi, deleteBusApi } from 'actions/admin/transport';
import colors from 'config/colors';
import BusFormModal from './BusFormModal';
import ExpiryFlags from './ExpiryFlags';
import { BUS_DOC_FIELDS } from '../transportUtils';

const STATUS_LABELS = { ACTIVE: 'Active', INACTIVE: 'Inactive', UNDER_MAINTENANCE: 'Under maintenance' };

// Buses: plain CRUD over /api/bus. Which route/driver a bus is on comes from the assignments the
// page loads (shown read-only here - assigning happens from the Routes tab).
const BusesTab = ({
  schoolId,
  loggedUserToken,
  showWarning,
  buses,
  isLoading,
  reload,
  refreshAssignments,
  onViewAssignment,
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editBus, setEditBus] = useState(null);
  const [saving, setSaving] = useState(false);

  const openAdd = () => {
    setEditBus(null);
    setIsModalOpen(true);
  };

  const openEdit = busId => {
    setEditBus(buses.find(b => b.busId === busId));
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditBus(null);
  };

  const handleSave = async formData => {
    setSaving(true);
    try {
      if (editBus) {
        // PUT replaces the whole bus, so send the existing record with the form's changes on top.
        await updateBusApi({
          busId: editBus.busId,
          postData: { ...editBus, ...formData, schoolId },
          token: loggedUserToken,
        });
      } else {
        await saveBusApi({ postData: { ...formData, schoolId }, token: loggedUserToken });
      }
      showWarning(editBus ? 'Bus updated successfully' : 'Bus added successfully', 'success');
      setSaving(false);
      closeModal();
      reload();
    } catch (err) {
      setSaving(false);
      showWarning(formResMessage(err), 'error');
    }
  };

  // MuiTable confirms before calling this, so it only ever runs after the admin said yes once.
  const handleDelete = async busId => {
    // Checked live, not against the list loaded earlier, so an assignment made since then still blocks this.
    const current = await refreshAssignments();
    if (current.some(a => a.busId === busId)) {
      showWarning('This bus is assigned to a driver and route. Unassign it first, then delete the bus.', 'error');
      return;
    }
    try {
      await deleteBusApi({ busId, token: loggedUserToken });
      showWarning('Bus deleted successfully', 'success');
      reload();
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
  };

  const rows = buses.map(bus => {
    return {
      ...bus,
      busLabel: (
        <span>
          <div>{bus.busNumber}</div>
          <div style={{ fontSize: 12, color: '#7d7d7d' }}>{bus.registrationNumber || '--'}</div>
        </span>
      ),
      specsLabel: (
        <span>
          <div>{[bus.make, bus.model].filter(Boolean).join(' ') || '--'}</div>
          <div style={{ fontSize: 12, color: '#7d7d7d' }}>
            {bus.seatingCapacity ? `${bus.seatingCapacity} seats` : '-- seats'}
          </div>
        </span>
      ),
      statusLabel:
        bus.status === 'ACTIVE' ? (
          <ActiveSpan status="Active" />
        ) : (
          <DeactiveSpan status={STATUS_LABELS[bus.status] || bus.status} />
        ),
      docsLabel: <ExpiryFlags record={bus} fields={BUS_DOC_FIELDS} />,
    };
  });

  if (isLoading) return <CommonLoader />;

  return (
    <>
      <Row className="mb-2" style={{ alignItems: 'center' }}>
        <Col style={{ textAlign: 'right' }}>
          <CustomButton
            size="small"
            name="+ Add Bus"
            onClick={openAdd}
            style={{ backgroundColor: colors.accent, color: colors.white }}
          />
        </Col>
      </Row>
      <MuiTable
        tableHeaders={['Bus', 'Make / Seats', 'Status', 'Documents', 'Action']}
        tableBodyData={{ content: rows }}
        bodyColumns={['busLabel', 'specsLabel', 'statusLabel', 'docsLabel', 'action']}
        idName="busId"
        dropDownActions={['edit', 'delete']}
        fetchItem={openEdit}
        deleteItem={handleDelete}
        hidePagination={true}
        renderRowExtra={bus => (
          <CustomButton
            size="small"
            variant="outlined"
            name="View assignment"
            onClick={() => onViewAssignment({ busId: bus.busId })}
          />
        )}
      />
      <BusFormModal isOpen={isModalOpen} editBus={editBus} saving={saving} onClose={closeModal} onSave={handleSave} />
    </>
  );
};

export default BusesTab;
