import React, { useEffect, useState } from 'react';
import StatTile from 'views/admin/Common/StatTile';
import { fetchTransportStudentCountApi } from 'actions/admin/transport';

// Head count of the students riding the school transport this year, with the biggest routes in the note. `refreshKey` refetches
// (e.g. after students are put on a route). When the count cannot be fetched the card is left out rather than shown empty.
const TransportCountCard = ({ schoolId, batchId, token, refreshKey }) => {
  const [counts, setCounts] = useState(null);

  useEffect(() => {
    if (!schoolId || !batchId || !token) {
      return undefined;
    }
    let cancelled = false;
    fetchTransportStudentCountApi({ schoolId, batchId, token })
      .then(data => !cancelled && setCounts(data))
      .catch(() => !cancelled && setCounts(null));
    return () => {
      cancelled = true;
    };
  }, [schoolId, batchId, token, refreshKey]);

  if (!counts) {
    return null;
  }
  const routes = [...(counts.routes || [])].sort((a, b) => b.studentCount - a.studentCount);
  const note = routes
    .slice(0, 3)
    .map(route => `${route.routeName} ${route.studentCount}`)
    .join(' · ');
  return (
    <div style={{ display: 'flex', marginBottom: 14 }}>
      <StatTile
        label="Transport students"
        value={counts.totalTransportStudents || 0}
        tone="info"
        note={note}
        minWidth={190}
        maxWidth={260}
      />
    </div>
  );
};

export default TransportCountCard;
