import React from 'react';
import { expiryState } from '../transportUtils';

const COLORS = { expired: '#c62828', soon: '#e65100' };

// Compact "what's lapsed or about to" summary for a record's expiry dates (fields: [{ key, label }]).
const ExpiryFlags = ({ record, fields }) => {
  const flags = fields.map(({ key, label }) => ({ label, ...expiryState(record[key]) })).filter(flag => flag.state);
  if (!flags.length) {
    // nothing lapsed or close: say so when dates are recorded, otherwise there is nothing to show
    return fields.some(({ key }) => record[key]) ? (
      <span style={{ color: '#2e7d32', fontSize: 12, fontWeight: 'bold' }}>All valid</span>
    ) : (
      <span style={{ color: '#9a9a9a' }}>Not set</span>
    );
  }
  return (
    <div style={{ fontSize: 12, lineHeight: 1.5 }}>
      {flags.map(flag => (
        <div key={flag.label} style={{ color: COLORS[flag.state], fontWeight: 'bold' }}>
          {flag.label} {flag.state === 'expired' ? 'expired' : `due in ${flag.days}d`}
        </div>
      ))}
    </div>
  );
};

export default ExpiryFlags;
