import React from 'react';
import { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import CustomButton from 'components/CustomButton';
import CustomSelect from 'components/CustomSelect';
import { CommonLoader } from 'views/admin/Common/Loader';
import StudentPicker from 'views/admin/Fees/components/StudentPicker';
import { formStudentName } from 'config/constants';
import { formResMessage, formCourseSelectList, toTitleCase } from 'utils/commonFunc';
import { fetchCourseStudentsListApi } from 'actions/admin/students';
import { fetchBatchCoursesPlainApi } from 'actions/admin/courses';
import { saveAssignedStudentsForTransportAreaService, deleteStudentTransportService } from 'actions/admin/transportFee';
import colors from 'config/colors';

// Students riding one route = the students assigned to its stops (the same StudentTransport records
// as Fees > Transport Fee, so the stop's fee applies to them there too). Names come from the
// school's student list, loaded once when the modal opens, since StudentTransport rows only carry ids.
const RouteStudentsModal = ({
  isOpen,
  route,
  areas,
  routeStudents,
  takenStudentIds,
  schoolId,
  batchId,
  loggedUserToken,
  showWarning,
  onClose,
  onChanged,
}) => {
  const [allStudents, setAllStudents] = useState([]);
  const [courseOptions, setCourseOptions] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isAdding, setIsAdding] = useState(false);
  const [areaId, setAreaId] = useState(null);
  const [selectedMap, setSelectedMap] = useState({});
  const [courseFilter, setCourseFilter] = useState('');
  const [searchText, setSearchText] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!isOpen) return;
    setIsAdding(false);
    setAreaId(null);
    setSelectedMap({});
    setCourseFilter('');
    setSearchText('');
    setIsLoading(true);
    // No endpoint lists a batch's students with their class, and the by-batch one caps at 50 per page,
    // so walk the batch's classes and take each class's full student list.
    fetchBatchCoursesPlainApi({ batchId, token: loggedUserToken })
      .then(async courseRes => {
        const courses = courseRes.data || [];
        const lists = await Promise.all(
          courses.map(c => fetchCourseStudentsListApi({ courseId: c.courseId, batchId, token: loggedUserToken }))
        );
        setAllStudents(
          lists.flatMap((res, index) =>
            (res.data || []).map(student => ({
              ...student,
              courseId: courses[index].courseId,
              courseName: courses[index].name,
            }))
          )
        );
        setCourseOptions(formCourseSelectList(courses));
      })
      .catch(err => showWarning(formResMessage(err), 'error'))
      .finally(() => setIsLoading(false));
  }, [isOpen]);

  const studentsById = allStudents.reduce((acc, s) => ({ ...acc, [s.studentId]: s }), {});
  const areasById = areas.reduce((acc, a) => ({ ...acc, [a.transportAreaId]: a }), {});

  const needle = searchText.trim().toLowerCase();
  const candidates = allStudents.filter(s => {
    if (courseFilter && s.courseId !== courseFilter) return false;
    if (!needle) return true;
    return (
      formStudentName(s).toLowerCase().includes(needle) || `${s.registerNumber || ''}`.toLowerCase().includes(needle)
    );
  });

  const toggleStudent = (student, checked) =>
    setSelectedMap(prev => {
      const next = { ...prev };
      if (checked) next[student.studentId] = student;
      else delete next[student.studentId];
      return next;
    });

  const handleAdd = async () => {
    const students = Object.values(selectedMap);
    if (!areaId) return showWarning('Pick the stop these students board at', 'error');
    if (!students.length) return showWarning('Select at least one student', 'error');
    setSaving(true);
    try {
      await saveAssignedStudentsForTransportAreaService({
        token: loggedUserToken,
        students,
        transportFeeStructId: route.transportFeeStructId,
        transportAreaId: areaId,
        schoolId,
        batchId,
      })();
      showWarning('Students added successfully', 'success');
      setIsAdding(false);
      setSelectedMap({});
      onChanged();
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
    setSaving(false);
  };

  const handleRemove = async row => {
    const name = studentsById[row.studentId] ? formStudentName(studentsById[row.studentId]) : 'this student';
    if (!window.confirm(`Remove ${toTitleCase(name)} from ${route.description}?`)) return;
    try {
      await deleteStudentTransportService({ studentTransportId: row.studentTransportId, token: loggedUserToken })();
      showWarning('Removed successfully', 'success');
      onChanged();
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
  };

  const areaOptions = areas.map(a => ({ value: a.transportAreaId, label: a.areaName }));
  const headStyle = { color: '#7d7d7d', fontSize: 12 };

  return (
    <Modal size="lg" isOpen={isOpen} toggle={onClose}>
      <ModalHeader toggle={onClose}>
        Students &mdash; {route?.description} ({routeStudents.length})
      </ModalHeader>
      <ModalBody>
        {isLoading ? (
          <div style={{ textAlign: 'center', padding: 20 }}>
            <CommonLoader />
          </div>
        ) : isAdding ? (
          <>
            <div style={{ fontSize: 12, color: '#9a9a9a', marginBottom: 10 }}>
              Added students ride this route and are charged the stop&apos;s transport fee, same as assigning them from
              Fees &gt; Transport Fee.
            </div>
            <CustomSelect
              label="Boarding stop"
              name="areaId"
              isRequired
              usePortal
              value={areaId}
              options={areaOptions}
              onChange={(name, value) => setAreaId(value)}
            />
            <div className="mt-3">
              <StudentPicker
                courseOptions={courseOptions}
                candidateStudents={candidates}
                courseFilter={courseFilter}
                searchText={searchText}
                onCourseFilterChange={setCourseFilter}
                onSearchTextChange={setSearchText}
                selectedMap={selectedMap}
                onToggle={toggleStudent}
                onClearAll={() => setSelectedMap({})}
                disabledStudentIds={takenStudentIds}
              />
            </div>
          </>
        ) : (
          <>
            <div style={{ textAlign: 'right', marginBottom: 8 }}>
              <CustomButton
                size="small"
                name="+ Add Students"
                disabled={!areas.length}
                onClick={() => setIsAdding(true)}
              />
            </div>
            {!areas.length && (
              <div style={{ fontSize: 12, color: '#9a9a9a', marginBottom: 8 }}>
                Add at least one stop to this route (Stops) before adding students.
              </div>
            )}
            {routeStudents.length ? (
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell style={headStyle}>
                      <b>Name</b>
                    </TableCell>
                    <TableCell style={headStyle}>
                      <b>Reg. No</b>
                    </TableCell>
                    <TableCell style={headStyle}>
                      <b>Class</b>
                    </TableCell>
                    <TableCell style={headStyle}>
                      <b>Stop</b>
                    </TableCell>
                    <TableCell align="right" style={headStyle}>
                      <b>Action</b>
                    </TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {routeStudents.map(row => {
                    const student = studentsById[row.studentId];
                    return (
                      <TableRow key={row.studentTransportId}>
                        <TableCell>
                          {student ? toTitleCase(formStudentName(student)) : `Student #${row.studentId}`}
                        </TableCell>
                        <TableCell>{student?.registerNumber || '--'}</TableCell>
                        <TableCell>{student?.courseName || '--'}</TableCell>
                        <TableCell>{areasById[row.transportAreaId]?.areaName || '--'}</TableCell>
                        <TableCell align="right">
                          <CustomButton
                            size="small"
                            variant="outlined"
                            color="default"
                            style={{ color: '#c62828', borderColor: '#c62828' }}
                            name="Remove"
                            onClick={() => handleRemove(row)}
                          />
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            ) : (
              <div style={{ textAlign: 'center', padding: 20, fontSize: 13, color: '#9a9a9a' }}>
                No students on this route yet.
              </div>
            )}
          </>
        )}
      </ModalBody>
      <ModalFooter>
        {isAdding ? (
          <>
            <CustomButton
              className="mr-2"
              type="button"
              color="default"
              disabled={saving}
              onClick={() => setIsAdding(false)}
              name="Back"
            />
            <CustomButton
              name="Add"
              disabled={saving}
              loading={saving}
              onClick={handleAdd}
              style={{ backgroundColor: colors.accent, color: colors.white }}
            />
          </>
        ) : (
          <CustomButton type="button" color="default" onClick={onClose} name="Close" />
        )}
      </ModalFooter>
    </Modal>
  );
};

export default RouteStudentsModal;
