import React from 'react';
import { useState } from 'react';
import { unassignRouteApi } from 'actions/admin/transport';
import { formResMessage } from 'utils/commonFunc';
import CustomButton from 'components/CustomButton';
import ConfirmModal from 'views/admin/Common/ConfirmModal';

// The "Unassign" button of one bus + driver + route assignment, for the action column, with a yes/no question first. Only
// the assignment is removed: the driver, the bus and the route stay, and can be assigned again.
const UnassignButton = ({
  assignment,
  label = 'Unassign driver',
  driverName,
  busNumber,
  routeName,
  loggedUserToken,
  showWarning,
  onDone,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  const confirm = async () => {
    setSaving(true);
    try {
      await unassignRouteApi({ driverRouteAssignmentId: assignment.driverRouteAssignmentId, token: loggedUserToken });
      showWarning('Driver unassigned from the route', 'success');
      setIsOpen(false);
      onDone();
    } catch (err) {
      showWarning(formResMessage(err), 'error');
    }
    setSaving(false);
  };

  return (
    <>
      <CustomButton size="small" variant="outlined" name={label} onClick={() => setIsOpen(true)} />
      <ConfirmModal
        size="md"
        loading={saving}
        confirmModalOpen={isOpen}
        confirmMessage={`Unassign ${driverName || 'this driver'}${busNumber ? ` (bus ${busNumber})` : ''} from ${
          routeName || 'this route'
        }? They will no longer see this route's students.`}
        deleteConfirm={confirm}
        deleteCancel={() => setIsOpen(false)}
      />
    </>
  );
};

export default UnassignButton;
